def events_page():
 return b.intro('Events','Events','')+event_showcase()+f'<section class="section white-section"><div class="wrap">{b.event_feed()}</div></section>'
def mosque():return b.intro('Namaz Timings','LUMS Mosque Namaz Timings',"Current prayer and Jama'at schedule observed at the central LUMS Mosque.")+prayer_scene()
def timings():
 return b.intro('Namaz Timings','LUMS Mosque Namaz Timings',"Current prayer and Jama'at schedule observed at the central LUMS Mosque.")+prayer_scene()+f'<section class="section white-section"><div class="wrap narrow prose"><h2>Namaz Timings</h2><p>Timetable source: LRS published schedule, snapshot 30 October 2026. Fajr, Asr and Isha follow its half-month rows. Zuhr and Jummah: 1:30 PM. Maghrib: calculated sunset plus one minute, following the original website’s rule.</p><p>The sky moves with your scroll. Congregation times remain the published schedule for the current Lahore date. Confirm special changes with the mosque.</p>{link("https://lrs.lums.edu.pk/namazTimings.html","View Full Monthly Timings & Mosque Guidelines","btn")}</div></section>'
def palestine():
 # Original site sections are retained verbatim in the source snapshot below.
 source=b.ROOT/'src/palestine-original-body.html'
 archive=source.read_text().replace('@@MEDIA@@',b.asset('media/')) if source.exists() else ''
 return f'''<section class="palestine-opening"><div class="solidarity-image">{img('community-7.jpg','LRS solidarity initiative, archival image','',False)}</div><div class="solidarity-curtain"></div>{ornament()}<div class="wrap"><p class="eyebrow">Humanitarian & Awareness Initiatives</p><h1><span>Palestinian</span><em>Solidarity</em></h1><p>Standing together for justice, humanitarian relief, historical awareness, and collective community action.</p><a class="btn" href="#take-action">Take action now ↗</a></div></section>
<section class="section humanitarian-intro white-section"><div class="wrap"><span class="chapter-mark" aria-hidden="true">01 /</span><h2>Lives.<br><em>Not statistics.</em></h2><div class="humanitarian-copy"><p>Families in Gaza face displacement, damaged infrastructure, and barriers to essential services. UNRWA’s 2026 appeal describes urgent needs across Gaza and the West Bank, including shelter, healthcare, food, and clean water.</p><p>Learning, peaceful advocacy, and supporting humanitarian relief are ways to respond.</p><a href="https://www.unrwa.org/resources/emergency-appeals/unrwa-occupied-palestinian-territory-flash-appeal-2026">Source: UNRWA 2026 appeal ↗</a></div></div></section>
<section class="solidarity-archive section"><div class="wrap">{archive}</div></section>
<section class="section action-section" id="take-action">{ornament()}<div class="wrap"><p class="eyebrow">Take action now</p><h2>Turn solidarity<br><em>into support.</em></h2><div class="action-grid"><a class="action-card" href="https://donate.unrwa.org/int/en/gaza"><span>01 / Humanitarian relief</span><h3>Donate to<br>UNRWA’s Gaza appeal.</h3><p>Continue to UNRWA’s official donation page.</p><b aria-hidden="true">↗</b></a><a class="action-card" href="https://www.ochaopt.org/"><span>02 / Stay informed</span><h3>Read verified<br>humanitarian updates.</h3><p>Follow reporting from the UN humanitarian coordination office.</p><b aria-hidden="true">↗</b></a><a class="action-card" href="{b.url('events/why-al-aqsa-still-calls-us')}"><span>03 / Learn together</span><h3>Why Al Aqsa<br>Still Calls Us.</h3><p>Explore the LRS solidarity event announcement.</p><b aria-hidden="true">↗</b></a></div><p class="fine">Donations are handled by UNRWA on its website. LRS does not collect payments through this page.</p></div></section>'''
def install(module):
 global b
 b=module
 for name in ['layout','home','pillars','highlights','event_showcase','prayer_scene','gallery','faq','events_page','mosque','timings','palestine']:
  setattr(b,name,globals()[name])
